// Local synthesized soundscape; no network, recordings or autoplay.
export class Soundscape {
 constructor(){this.enabled=false;this.context=null;this.step=0;this.pulse=0;this.nodes=[]}
 toggle(){this.enabled=!this.enabled;if(this.enabled){this.context??=new AudioContext();this.context.resume()}else this.context?.suspend();return this.enabled}
 tone(frequency,duration=.4,gain=.08,type='sine',pan=0){if(!this.enabled)return;const c=this.context,o=c.createOscillator(),g=c.createGain(),p=c.createStereoPanner();o.type=type;o.frequency.setValueAtTime(frequency,c.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(12,frequency*.45),c.currentTime+duration);g.gain.setValueAtTime(.001,c.currentTime);g.gain.exponentialRampToValueAtTime(gain,c.currentTime+.015);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);p.pan.value=Math.max(-1,Math.min(1,pan));o.connect(g).connect(p).connect(c.destination);o.start();o.stop(c.currentTime+duration);o.onended=()=>{o.disconnect();g.disconnect();p.disconnect()}}
 update(dt,chase,distance,memoryDistance){if(!this.enabled)return;this.step-=dt;this.pulse-=dt;if(this.step<=0){this.step=chase?.5:1.2;this.tone(42,.65,Math.max(.004,.16-distance*.012),'triangle');if(chase)this.tone(110,.3,.018,'sawtooth')}if(this.pulse<=0){this.pulse=2.8;this.tone(55,2.6,.012);if(memoryDistance<5)this.tone(580,1,.035*(1-memoryDistance/6),'sine');}}
 memory(){for(let i=0;i<4;i++)this.tone(220+i*83,1.3,.03)}
}

